-- Roadmap 2.8: playback renditions of videos and audio (H.264/AAC MP4), generated by the media
-- worker like thumbnails. Videos also get THUMB/PREVIEW stills. Same rules as thumbnails: the
-- original is never modified, renditions can be regenerated, and they are not part of the proof.
ALTER TABLE asset_derivatives DROP CONSTRAINT asset_derivatives_variant_check;
ALTER TABLE asset_derivatives ADD CONSTRAINT asset_derivatives_variant_check
    CHECK (variant IN ('THUMB', 'PREVIEW', 'PLAYBACK'));
